/** NOTE: The sourceX2 is exclusive. */
public void copyInterval(TerminalRow line, int sourceX1, int sourceX2, int destinationX) {
    mHasNonOneWidthOrSurrogateChars |= line.mHasNonOneWidthOrSurrogateChars;
    final int x1 = line.findStartOfColumn(sourceX1);
    final int x2 = line.findStartOfColumn(sourceX2);
    boolean startingFromSecondHalfOfWideChar = (sourceX1 > 0 && line.wideDisplayCharacterStartingAt(sourceX1 - 1));
    final char[] sourceChars = (this == line) ? Arrays.copyOf(line.mText, line.mText.length) : line.mText;
    int latestNonCombiningWidth = 0;
    for (int i = x1; i < x2; i++) {
        char sourceChar = sourceChars[i];
        int codePoint = Character.isHighSurrogate(sourceChar) ? Character.toCodePoint(sourceChar, sourceChars[++i]) : sourceChar;
        if (startingFromSecondHalfOfWideChar) {
            // Just treat copying second half of wide char as copying whitespace.
            codePoint = ' ';
            startingFromSecondHalfOfWideChar = false;
        }
        int w = WcWidth.width(codePoint);
        if (w > 0) {
            destinationX += latestNonCombiningWidth;
            sourceX1 += latestNonCombiningWidth;
            latestNonCombiningWidth = w;
        }
        setChar(destinationX, codePoint, line.getStyle(sourceX1));
    }
}

public int getSpaceUsed() {
    return mSpaceUsed;
}

/** Note that the column may end of second half of wide character. */
public int findStartOfColumn(int column) {
    if (column == mColumns) return getSpaceUsed();

    int currentColumn = 0;
    int currentCharIndex = 0;
    while (true) { // 0<2 1 < 2
        int newCharIndex = currentCharIndex;
        char c = mText[newCharIndex++]; // cci=1, cci=2
        boolean isHigh = Character.isHighSurrogate(c);
        int codePoint = isHigh ? Character.toCodePoint(c, mText[newCharIndex++]) : c;
        int wcwidth = WcWidth.width(codePoint); // 1, 2
        if (wcwidth > 0) {
            currentColumn += wcwidth;
            if (currentColumn == column) {
                // Skip any following combining chars (width <= 0).
                while (newCharIndex < mSpaceUsed && WcWidth.width(mText, newCharIndex) <= 0)
                    newCharIndex += Character.isHighSurrogate(mText[newCharIndex]) ? 2 : 1;
                return newCharIndex;
            } else if (currentColumn > column) {
                // Wide column going past end.
                return currentCharIndex;
            }
        }
        currentCharIndex = newCharIndex;
    }
}

private boolean wideDisplayCharacterStartingAt(int column) {
    for (int currentCharIndex = 0, currentColumn = 0; currentCharIndex < mSpaceUsed; ) {
        char c = mText[currentCharIndex++];
        int codePoint = Character.isHighSurrogate(c) ? Character.toCodePoint(c, mText[currentCharIndex++]) : c;
        int wcwidth = WcWidth.width(codePoint);
        if (wcwidth > 0) {
            if (currentColumn == column && wcwidth == 2) return true;
            currentColumn += wcwidth;
            if (currentColumn > column) return false;
        }
    }
    return false;
}

public void clear(long style) {
    Arrays.fill(mText, ' ');
    Arrays.fill(mStyle, style);
    mSpaceUsed = (short) mColumns;
    mHasNonOneWidthOrSurrogateChars = false;
}

// https://github.com/steven676/Android-Terminal-Emulator/commit/9a47042620bec87617f0b4f5d50568535668fe26
public void setChar(int columnToSet, int codePoint, long style) {
    if (columnToSet  < 0 || columnToSet >= mStyle.length)
        throw new IllegalArgumentException("TerminalRow.setChar(): columnToSet=" + columnToSet + ", codePoint=" + codePoint + ", style=" + style);

    mStyle[columnToSet] = style;

    final int newCodePointDisplayWidth = WcWidth.width(codePoint);

    // Fast path when we don't have any chars with width != 1
    if (!mHasNonOneWidthOrSurrogateChars) {
        if (codePoint >= Character.MIN_SUPPLEMENTARY_CODE_POINT || newCodePointDisplayWidth != 1) {
            mHasNonOneWidthOrSurrogateChars = true;
        } else {
            mText[columnToSet] = (char) codePoint;
            return;
        }
    }

    final boolean newIsCombining = newCodePointDisplayWidth <= 0;

    boolean wasExtraColForWideChar = (columnToSet > 0) && wideDisplayCharacterStartingAt(columnToSet - 1);

    if (newIsCombining) {
        // When standing at second half of wide character and inserting combining:
        if (wasExtraColForWideChar) columnToSet--;
    } else {
        // Check if we are overwriting the second half of a wide character starting at the previous column:
        if (wasExtraColForWideChar) setChar(columnToSet - 1, ' ', style);
        // Check if we are overwriting the first half of a wide character starting at the next column:
        boolean overwritingWideCharInNextColumn = newCodePointDisplayWidth == 2 && wideDisplayCharacterStartingAt(columnToSet + 1);
        if (overwritingWideCharInNextColumn) setChar(columnToSet + 1, ' ', style);
    }

    char[] text = mText;
    final int oldStartOfColumnIndex = findStartOfColumn(columnToSet);
    final int oldCodePointDisplayWidth = WcWidth.width(text, oldStartOfColumnIndex);

    int oldCharactersUsedForColumn = countCharsUsedByColumn(columnToSet, oldCodePointDisplayWidth, oldStartOfColumnIndex);

